function renderModule(id){const f={binary:binaryLab,classes:classesLab,masks:maskLab,cidr:cidrLab,tree:treeLab,vlsm:vlsmLab,overlap:aggregateLab,supernet:aggregateLab,summary:aggregateLab,'ospf-summary':aggregateLab,ipv6:ipv6Lab,password:passwordLab,mac:macLab,units:unitsLab,wireguard:wireguardLab,ping:pingLab,asn:asnLab,'asn-ref':asnLab,ports:portsLab,mtu:mtuLab,tunnel:tunnelLab,vlan:vlanLab,eigrp:eigrpLab,'tcp-state':tcpStateLab,tracer:packetTraceLab};if(f[id])return f[id](id);if(SCENARIOS[id])return simulationLab(id);if(typeof routingModule==='function'&&routingModule(id))return;if(typeof learningModule==='function'&&learningModule(id))return;throw Error('This lab is not configured.');}
function binaryLab(){$('surface').innerHTML=card('Decimal ↔ binary',`<div class="fields">${input('dec','Decimal octet',192,'number','min="0" max="255"')}${input('bin','8-bit binary','11000000')}</div>${out('builder')}${out()}`)+card('Bitwise AND',`<div class="fields">${input('and-ip','IP address','192.168.10.74')}${input('and-mask','Mask','255.255.255.0')}</div>${btn('and','Calculate AND',true)}${out('and-result')}`);const draw=n=>{if(!Number.isInteger(n)||n<0||n>255)throw Error('Use an integer from 0 to 255.');$('dec').value=n;$('bin').value=n.toString(2).padStart(8,'0');$('builder').innerHTML=`<div class="bits">${Array.from({length:8},(_,i)=>`<button class="bit ${n&(1<<(7-i))?'':'host'}" data-bit="${7-i}" aria-label="Toggle bit ${7-i}">${n>>(7-i)&1}</button>`).join('')}</div><div class="bits">${[128,64,32,16,8,4,2,1].map(n=>`<span style="flex:1;text-align:center;color:var(--muted);font-size:13px">${n}</span>`).join('')}</div>`;$('output').innerHTML=hint(`Active bit weights: ${[128,64,32,16,8,4,2,1].filter(v=>n&v).join(' + ')||'0'} = <strong>${n}</strong>.`);$('builder').querySelectorAll('button').forEach(b=>b.onclick=()=>draw(n^(1<<Number(b.dataset.bit))));};$('dec').oninput=()=>safe(()=>draw(Number($('dec').value)));$('bin').onchange=()=>safe(()=>{if(!/^[01]{8}$/.test($('bin').value))throw Error('Enter exactly eight binary digits.');draw(parseInt($('bin').value,2));});action('and',()=>{const a=Net.ip($('and-ip').value),m=Net.ip($('and-mask').value),r=(a&m)>>>0;$('and-result').innerHTML=`<pre>IP       ${Net.binary(a)}\nMask     ${Net.binary(m)}\nResult   ${Net.binary(r)}\n\n${Net.str(r)}</pre>`;});draw(192);$('and').click();}
function classesLab(){$('surface').innerHTML=card('Address classification',`<div class="fields">${input('class-ip','IPv4 address','172.20.10.1')}</div>${btn('classify','Inspect address',true)}${out()}`)+card('Historical class boundaries',table(['Class','First octet','Default prefix','Purpose'],[['A','1–126','/8','Historical unicast'],['B','128–191','/16','Historical unicast'],['C','192–223','/24','Historical unicast'],['D','224–239','—','Multicast'],['E','240–255','—','Reserved']])+hint('Modern routing uses CIDR. An address ending in .0 or .255 can be a usable host depending on its actual subnet mask.'))+card('Private and special ranges',table(['Prefix','Meaning'],[['10.0.0.0/8','Private'],['172.16.0.0/12','Private'],['192.168.0.0/16','Private'],['127.0.0.0/8','Loopback'],['169.254.0.0/16','Link-local'],['192.0.2.0/24','Documentation'],['198.51.100.0/24','Documentation'],['203.0.113.0/24','Documentation']]));action('classify',()=>{const c=Net.classify($('class-ip').value);$('output').innerHTML=stats([['Historical class',c.class],['Category',c.type],['Binary address',Net.binary(Net.ip($('class-ip').value)),'full']]);});$('classify').click();}
function maskLab(){$('surface').innerHTML=card('Prefix boundary',input('mask-p','Prefix length',24,'range','min="0" max="32" step="1"')+out('mask-bits')+out());const run=()=>{const n=Net.subnet('0.0.0.0',$('mask-p').value);$('mask-bits').innerHTML=`<h3>/${n.p} · ${n.mask}</h3>`+bitMap(Net.ip(n.mask),n.p);$('output').innerHTML=stats([['Network bits',n.p],['Host bits',32-n.p],['Block size',n.size.toLocaleString()],['Usable addresses',n.hosts.toLocaleString()],['Wildcard mask',n.wildcard,'full']]);};$('mask-p').oninput=run;run();}
function cidrLab(){$('surface').innerHTML=card('Block explorer',`<div class="fields">${input('cidr','CIDR block','172.16.0.0/20')}${input('child-p','Split into prefix',24,'number','min="0" max="32"')}</div>${btn('divide','Explore & divide',true)}${out()}`);action('divide',()=>{const b=Net.subnet($('cidr').value),p=Number($('child-p').value);if(!Number.isInteger(p)||p<b.p||p>32)throw Error('Child prefix must be at least the parent prefix and at most 32.');const count=2**(p-b.p);$('output').innerHTML=stats([['Normalized block',b.cidr],['Final address',b.lastAddress],['Equal subnets',count.toLocaleString()],['Addresses per child',(2**(32-p)).toLocaleString()]])+hint(count>256?'Showing the first 256 subnets.':'Each child covers an equally sized, aligned block.')+table(['CIDR','Usable range','Hosts'],Array.from({length:Math.min(count,256)},(_,i)=>{const n=Net.subnet(Net.str(b.start+i*2**(32-p)),p);return[n.cidr,n.first+' – '+n.last,n.hosts.toLocaleString()];}));});$('divide').click();}
function treeLab(){$('surface').innerHTML=card('Starting block',`<div class="fields">${input('tree-base','Network','192.168.10.0/24')}</div>${btn('tree-build','Build tree',true)}${out()}`);let blocks=[];const draw=()=>{$('output').innerHTML=table(['Subnet','Mask','Address range','Usable','Actions'],blocks.map((n,i)=>[n.cidr,n.mask,n.network+' – '+n.lastAddress,n.hosts,`<button data-split="${i}" ${n.p===32?'disabled':''}>Split</button> <button data-join="${i}" ${n.p===Net.subnet($('tree-base').value).p?'disabled':''}>Join siblings</button>`]));$('output').querySelectorAll('[data-split]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.split),n=blocks[i];blocks.splice(i,1,Net.subnet(n.network,n.p+1),Net.subnet(Net.str(n.start+n.size/2),n.p+1));draw();});$('output').querySelectorAll('[data-join]').forEach(b=>b.onclick=()=>safe(()=>{const i=Number(b.dataset.join),n=blocks[i],parent=Net.subnet(n.network,n.p-1);const siblings=blocks.filter(x=>x.p===n.p&&x.start>=parent.start&&x.end<=parent.end);if(siblings.length!==2)throw Error('Join the smaller descendants first so both siblings have the same prefix.');blocks=blocks.filter(x=>!siblings.includes(x));blocks.push(parent);blocks.sort((a,b)=>a.start-b.start);draw();}));};action('tree-build',()=>{blocks=[Net.subnet($('tree-base').value)];draw();});$('tree-build').click();}
function vlsmLab(){$('surface').innerHTML=card('Plan address space',`<div class="fields">${input('vlsm-base','Base block','192.168.10.0/24')}</div><div id="requirements"></div><div class="actions">${btn('add-req','Add subnet')}${btn('allocate','Allocate largest first',true)}</div>${out()}`);let n=0;const add=(name,hosts)=>{const row=document.createElement('div');row.className='fields';row.innerHTML=input('req-name-'+n,'Subnet name',name)+input('req-host-'+n,'Hosts needed',hosts,'number','min="1"')+`<button aria-label="Remove subnet">Remove</button>`;row.querySelector('button').onclick=()=>row.remove();$('requirements').append(row);n++;};add('Users',100);add('Servers',50);add('Management',12);action('add-req',()=>add('Subnet '+(n+1),10));action('allocate',()=>{const rows=[...$('requirements').children];if(!rows.length)throw Error('Add at least one subnet requirement.');const req=rows.map(r=>({name:r.querySelector('input').value,hosts:Number(r.querySelector('input[type=number]').value)}));const a=Net.vlsm(Net.subnet($('vlsm-base').value),req);$('output').innerHTML=table(['Name','Required','CIDR','Usable range','Capacity'],a.map(x=>[esc(x.name),x.required,x.cidr,x.first+' – '+x.last,x.size-2]))+hint('Larger blocks are allocated first to preserve alignment. These allocations reserve network and broadcast addresses.');});$('allocate').click();}
function aggregateLab(id){const overlaps=id==='overlap',title=overlaps?'Check address ranges':'Aggregate prefixes';$('surface').innerHTML=card(title,area('prefixes','CIDR blocks, one per line',overlaps?'192.168.10.0/24\n192.168.10.128/25\n10.0.0.0/8':'192.168.0.0/24\n192.168.1.0/24\n192.168.2.0/24\n192.168.3.0/24')+`<div class="actions">${btn('aggregate',overlaps?'Check every pair':'Calculate summaries',true)}${btn('aggregate-copy','Copy result')}</div>`+out());let text='';action('aggregate',()=>{const a=Net.list($('prefixes').value);if(overlaps){const o=Net.overlap(a);text=o.map(r=>r.join(' | ')).join('\n')||'No overlaps.';$('output').innerHTML=o.length?table(['Network A','Network B','Overlap start','Overlap end'],o):hint('No overlapping address ranges were found.');}else{const n=Net.summarize(a),exact=Net.merge(a),covered=exact.reduce((s,b)=>s+b.size,0);text=exact.map(b=>b.cidr).join('\n');$('output').innerHTML=stats([['Covering aggregate',n.cidr,'highlight'],['Included addresses',n.size.toLocaleString()],['Input coverage',covered.toLocaleString()],['Extra addresses',(n.size-covered).toLocaleString()]])+hint(n.size>covered?'The covering summary includes space absent from the input. Exact summaries below preserve only the supplied coverage.':'The covering summary exactly matches the supplied address space.')+table(['Exact aggregate','Mask','Address count'],exact.map(b=>[b.cidr,b.mask,b.size.toLocaleString()]))+`<pre>${esc(exact.map(b=>id==='ospf-summary'?`area 1 range ${b.network} ${b.mask}`:`ip route ${b.network} ${b.mask} Null0`).join('\n'))}</pre>`;}});action('aggregate-copy',()=>copy(text));$('aggregate').click();}
function ipv6Lab(){$('surface').innerHTML=`<div class="chips" id="v6-tabs">${['Address analyzer','Subnetting','EUI-64 / SLAAC','Transition','Reference'].map((x,i)=>`<button data-v6="${i}">${x}</button>`).join('')}</div><div id="v6-panel" style="margin-top:20px"></div>`;const page=i=>{if(i===0){$('v6-panel').innerHTML=card('Analyze and normalize',input('v6','IPv6 address','2001:db8:85a3::8a2e:370:7334')+`<div class="actions">${btn('v6-run','Analyze',true)}</div>`+out());action('v6-run',()=>{const a=Net.expand6($('v6').value),n=Net.int6($('v6').value),first=parseInt(a[0],16);let type=n===0n?'Unspecified':n===1n?'Loopback':(first&0xff00)===0xff00?'Multicast':(first&0xffc0)===0xfe80?'Link-local':(first&0xfe00)===0xfc00?'Unique local':(first&0xe000)===0x2000?'Global-unicast allocation space':'Other / special-purpose';if(a[0]==='2001'&&a[1]==='0db8')type='Documentation (2001:db8::/32)';$('output').innerHTML=stats([['Expanded',a.join(':'),'full'],['Compressed',Net.compress6(a),'full'],['Address type',type],['Length','128 bits'],['Reverse PTR',a.join('').split('').reverse().join('.')+'.ip6.arpa','full']])+`<pre>${a.map(x=>parseInt(x,16).toString(2).padStart(16,'0')).join('\n')}</pre>`;});$('v6-run').click();}else if(i===1){$('v6-panel').innerHTML=card('Divide IPv6 space',`<div class="fields">${input('v6-base','Parent prefix','2001:db8::/48')}${input('v6-child','Child prefix',64,'number','min="0" max="128"')}</div>${btn('v6-divide','Divide',true)}${out()}`);action('v6-divide',()=>{const b=Net.subnet6($('v6-base').value),p=Number($('v6-child').value);if(!Number.isInteger(p)||p<b.p||p>128)throw Error('Child prefix must be between the parent prefix and 128.');const count=1n<<BigInt(p-b.p),size=1n<<BigInt(128-p);$('output').innerHTML=stats([['Parent network',b.cidr,'full'],['Child networks',count.toString()],['Addresses per child',size.toString()]])+hint('Showing at most 128 child prefixes. IPv6 uses multicast rather than broadcast.')+table(['Child prefix'],Array.from({length:Number(count>128n?128n:count)},(_,j)=>[Net.str6(b.start+BigInt(j)*size)+'/'+p]));});$('v6-divide').click();}else if(i===2){$('v6-panel').innerHTML=card('Modified EUI-64 interface ID',`<div class="fields">${input('eui-mac','MAC address','02:11:22:33:44:55')}${input('eui-prefix','Network /64','2001:db8:1::/64')}</div>${btn('eui','Build address',true)}${out()}`+hint('Modern clients often use stable or temporary privacy addresses instead of MAC-derived EUI-64.'));action('eui',()=>{const m=Net.mac($('eui-mac').value).map(x=>parseInt(x,16)),b=Net.subnet6($('eui-prefix').value);if(b.p!==64)throw Error('Use a /64 network for this SLAAC example.');m[0]^=2;const bytes=[...m.slice(0,3),255,254,...m.slice(3)],iid=BigInt('0x'+bytes.map(x=>x.toString(16).padStart(2,'0')).join(''));$('output').innerHTML=stats([['Interface ID',bytes.map(x=>x.toString(16).padStart(2,'0')).join(':'),'full'],['SLAAC address',Net.str6(b.start+iid),'full']]);});$('eui').click();}else if(i===3){$('v6-panel').innerHTML=card('IPv4 embedding',input('embed-ip','IPv4 address','192.0.2.10')+`<div class="actions">${btn('embed','Convert',true)}</div>`+out());action('embed',()=>{const n=Net.ip($('embed-ip').value),hex=Math.floor(n/65536).toString(16)+':'+(n%65536).toString(16);$('output').innerHTML=stats([['IPv4-mapped','::ffff:'+hex,'full'],['NAT64 well-known prefix','64:ff9b::'+hex,'full'],['6to4 prefix (legacy)','2002:'+hex+'::/48','full']])+hint('Mapped addresses represent IPv4 in an IPv6 API. NAT64 is a translation deployment. 6to4 is a legacy transition mechanism, not a recommended new deployment.');});$('embed').click();}else $('v6-panel').innerHTML=card('IPv6 reference',table(['Prefix','Use'],[['::/128','Unspecified'],['::1/128','Loopback'],['2000::/3','Current global-unicast allocation space'],['2001:db8::/32','Documentation'],['fc00::/7','Unique local'],['fe80::/10','Link-local'],['ff00::/8','Multicast'],['ff02::1','All nodes on link'],['ff02::2','All routers on link'],['ff02::5','OSPF routers']]));$('v6-tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.v6)===i));};$('v6-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>safe(()=>page(Number(b.dataset.v6))));page(0);}
function passwordLab(){$('surface').innerHTML=card('Password options',`<div class="fields">${select('pass-style','Style',['Random characters','Passphrase'])}${input('pass-len','Length / word count',20,'number','min="4" max="128"')}</div><div class="fields">${['Uppercase','Lowercase','Numbers','Symbols'].map((x,i)=>`<label><input type="checkbox" id="set-${i}" checked> ${x}</label>`).join('')}</div><div class="actions">${btn('generate','Generate locally',true)}${btn('pass-copy','Copy password')}</div>${out()}`+hint('Passwords stay in this browser. Generation uses rejection sampling with crypto.getRandomValues, without a remote service.'));let password='';const sets=['ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz','0123456789','!@#$%^&*()-_=+[]{}:,.?'];const words='acorn anchor apple atlas autumn beacon birch bloom breeze brook canyon cedar cloud cobalt coral cosmos crane crystal dawn delta dune eagle ember fern field flame forest frost galaxy garden harbor hazel horizon island ivory jade juniper kiwi lake lantern lemon lunar maple meadow mint mist mountain nectar ocean olive orbit otter pebble pine planet plum quartz raven reed ridge river robin rocket saffron sage sail silver slate snow solar sparrow spring stone storm summit sunset teal timber trail tulip valley violet willow winter wren zephyr'.split(' ');action('generate',()=>{const len=Number($('pass-len').value);if(!Number.isInteger(len)||len<4||len>128)throw Error('Length must be an integer between 4 and 128.');let bits;if($('pass-style').value==='Passphrase'){if(len>12)throw Error('Choose 4–12 words for a passphrase.');password=Array.from({length:len},()=>words[Net.randomInt(words.length)]).join('-');bits=len*Math.log2(words.length);}else{const active=sets.filter((x,i)=>$('set-'+i).checked);if(!active.length)throw Error('Select at least one character set.');const pool=active.join('');do{password=Array.from({length:len},()=>pool[Net.randomInt(pool.length)]).join('');}while(active.some(s=>![...password].some(c=>s.includes(c))));bits=len*Math.log2(pool.length);} $('output').innerHTML=`<pre style="font-size:22px">${esc(password)}</pre>`+stats([['Estimated search-space bits',Math.floor(bits)],['Generated length',password.length]])+hint('Search-space estimates assume a random draw. Character-class requirements reduce the exact space slightly. The compact passphrase dictionary is intended for learning.');});$('pass-style').onchange=()=>{$('pass-len').value=$('pass-style').value==='Passphrase'?5:20;};action('pass-copy',()=>copy(password));$('generate').click();}
function macLab(){$('surface').innerHTML=card('MAC address formats',input('mac','MAC address','02:11:22:33:44:55')+`<div class="actions">${btn('mac-run','Convert',true)}${btn('mac-random','Random local address')}</div>`+out());action('mac-run',()=>{const a=Net.mac($('mac').value),s=a.join(''),first=parseInt(a[0],16);$('output').innerHTML=stats([['Colon',a.join(':')],['Hyphen',a.join('-')],['Cisco dot',s.match(/.{4}/g).join('.')],['Plain hex',s],['Delivery',first&1?'Multicast / group':'Unicast / individual'],['Administration',first&2?'Locally administered':'Universally administered'],['OUI / first three bytes',a.slice(0,3).join('-'),'full']])+hint('An OUI alone does not identify a vendor for locally administered addresses. This lab does not infer vendors without a registry lookup.');});action('mac-random',()=>{const b=crypto.getRandomValues(new Uint8Array(6));b[0]=(b[0]|2)&254;$('mac').value=[...b].map(n=>n.toString(16).padStart(2,'0')).join(':');$('mac-run').click();});$('mac-run').click();}
function unitsLab(){$('surface').innerHTML=card('Network quantity converter',`<div class="fields">${select('unit-mode','Converter',['Data size','Bandwidth','Transfer time','Bandwidth-delay product','TCP MSS','Number base','QoS serialization','Goodput','Timers','Packet rate'])}</div><div id="unit-fields"></div>${btn('convert','Calculate',true)}${out()}`);const specs={ 'Data size':[['u-a','Bytes',1048576],['u-b','Binary exponent (KiB=10, MiB=20)',20]],Bandwidth:[['u-a','Megabits per second',1000]],'Transfer time':[['u-a','File size (MB, decimal)',1000],['u-b','Link rate (Mbps)',100]],'Bandwidth-delay product':[['u-a','Link rate (Mbps)',100],['u-b','Round-trip time (ms)',50]],'TCP MSS':[['u-a','MTU (bytes)',1500],['u-b','IP + TCP header bytes',40]],'Number base':[['u-a','Decimal integer',192]],'QoS serialization':[['u-a','Packet size (bytes)',1500],['u-b','Link rate (Mbps)',10]],Goodput:[['u-a','Link rate (Mbps)',100],['u-b','Payload bytes',1460],['u-c','Total on-wire bytes',1538]],Timers:[['u-a','Milliseconds',500]],'Packet rate':[['u-a','Link rate (Mbps)',1000],['u-b','On-wire packet bytes',1538]]};const fields=()=>{$('unit-fields').innerHTML=`<div class="fields">${specs[$('unit-mode').value].map(([id,label,value])=>input(id,label,value,'number','min="0" step="any"')).join('')}</div>`;};action('convert',()=>{const m=$('unit-mode').value,a=Number($('u-a').value),b=$('u-b')?Number($('u-b').value):0,c=$('u-c')?Number($('u-c').value):0;if(!Number.isFinite(a)||a<0||($('u-b')&&(!Number.isFinite(b)||b<0)))throw Error('Use nonnegative finite values.');let r;switch(m){case'Data size':if(!Number.isInteger(b)||b>60)throw Error('Use an exponent 0–60.');r=[['Binary units',(a/2**b).toLocaleString()],['Bits',(a*8).toLocaleString()]];break;case'Bandwidth':r=[['Bytes per second',(a*1e6/8).toLocaleString()],['Gbps',(a/1000).toLocaleString()]];break;case'Transfer time':if(b===0)throw Error('Link rate must be positive.');r=[['Ideal seconds',(a*8/b).toFixed(3)]];break;case'Bandwidth-delay product':r=[['Window bytes',(a*1e6*b/1000/8).toLocaleString()]];break;case'TCP MSS':if(a<=b)throw Error('MTU must exceed header size.');r=[['Maximum TCP payload bytes',a-b]];break;case'Number base':if(!Number.isSafeInteger(a))throw Error('Use a nonnegative safe integer.');r=[['Hexadecimal','0x'+a.toString(16).toUpperCase()],['Binary',a.toString(2)]];break;case'QoS serialization':if(!b)throw Error('Rate must be positive.');r=[['Serialization delay (ms)',(a*8/b/1000).toFixed(4)]];break;case'Goodput':if(c<=0||b>c)throw Error('Total bytes must be positive and at least the payload.');r=[['Ideal goodput (Mbps)',(a*b/c).toFixed(3)],['Efficiency', (b/c*100).toFixed(2)+'%']];break;case'Timers':r=[['Seconds',a/1000],['Microseconds',a*1000]];break;case'Packet rate':if(!b)throw Error('Packet size must be positive.');r=[['Packets per second',Math.floor(a*1e6/(8*b)).toLocaleString()]];} $('output').innerHTML=stats(r)+hint('These are ideal arithmetic estimates. Protocol overhead, contention and loss affect real measurements.');});$('unit-mode').onchange=()=>{fields();$('convert').click();};fields();$('convert').click();}
function wireguardLab(){$('surface').innerHTML=card('X25519 key material',`<div class="actions">${btn('wg-generate','Generate key pair',true)}${btn('wg-psk','Generate preshared key')}</div>${out('keys')}`)+card('Configuration builder',`<div class="fields">${input('wg-addr','Interface address','10.50.0.1/24')}${input('wg-peer','Peer public key','')}${input('wg-endpoint','Endpoint','vpn.example.com:51820')}${input('wg-allowed','Allowed IPs','10.50.0.0/24')}</div><div class="actions">${btn('wg-config','Build config',true)}${btn('wg-download','Download config')}</div>${out()}`+hint('Keys are generated locally. Downloaded configurations contain a private key: keep them private.'));let priv='',pub='',psk='',config='';const b64=b=>btoa(String.fromCharCode(...b));const draw=()=>$('keys').innerHTML=stats([['Private key',priv||'Generate a key pair','full'],['Public key',pub||'—','full'],['Preshared key',psk||'Optional','full']]);action('wg-generate',async()=>{const pair=await crypto.subtle.generateKey({name:'X25519'},true,['deriveBits']);const raw=new Uint8Array(await crypto.subtle.exportKey('pkcs8',pair.privateKey));const bytes=raw.slice(-32);bytes[0]&=248;bytes[31]&=127;bytes[31]|=64;priv=b64(bytes);pub=b64(new Uint8Array(await crypto.subtle.exportKey('raw',pair.publicKey)));draw();});action('wg-psk',()=>{psk=b64(crypto.getRandomValues(new Uint8Array(32)));draw();});action('wg-config',()=>{if(!priv)throw Error('Generate a key pair first.');Net.subnet($('wg-addr').value);const peer=$('wg-peer').value.trim();if(!/^[A-Za-z0-9+/]{43}=$/.test(peer))throw Error('Enter a 32-byte base64 peer public key.');Net.list($('wg-allowed').value);if(!/^[a-zA-Z0-9.\[\]:-]+:\d+$/.test($('wg-endpoint').value))throw Error('Use an endpoint host:port.');config=`[Interface]\nPrivateKey = ${priv}\nAddress = ${$('wg-addr').value}\n\n[Peer]\nPublicKey = ${peer}\n${psk?'PresharedKey = '+psk+'\n':''}AllowedIPs = ${$('wg-allowed').value}\nEndpoint = ${$('wg-endpoint').value}\nPersistentKeepalive = 25`; $('output').innerHTML=`<pre>${esc(config)}</pre>`;});action('wg-download',()=>{if(!config)throw Error('Build a valid configuration first.');download('wg0.conf',config);});draw();}
function pingLab(){$('surface').innerHTML=card('Simulated ping',`<div class="fields">${input('ping-target','Target label','192.0.2.1')}${select('ping-profile','Profile',['LAN','Routed LAN','Regional WAN','LTE','Intercontinental','Satellite','Congested'])}${input('ping-count','Count',10,'number','min="1" max="100"')}</div><div class="actions">${btn('ping-run','Run simulation',true)}${btn('ping-stop','Stop')}</div>${out()}`+hint('This is an educational simulation. It sends no ICMP packets and does not measure your actual connection.'));let timer=null,lines=[],values=[],sent=0;const profiles={LAN:[1,.2,0],'Routed LAN':[4,1,0],'Regional WAN':[30,8,.01],LTE:[65,25,.03],Intercontinental:[180,25,.01],Satellite:[600,70,.02],Congested:[120,100,.2]};const render=()=>{const lost=sent-values.length,avg=values.reduce((a,b)=>a+b,0)/(values.length||1),jitter=values.length>1?values.slice(1).reduce((s,v,i)=>s+Math.abs(v-values[i]),0)/(values.length-1):0;$('output').innerHTML=`<pre>${esc(lines.join('\n'))}</pre>`+stats([['Sent / received',sent+' / '+values.length],['Packet loss',sent?(lost/sent*100).toFixed(1)+'%':'—'],['Average RTT',values.length?avg.toFixed(2)+' ms':'—'],['Jitter (mean successive RTT delta)',jitter.toFixed(2)+' ms']])+`<div style="display:flex;align-items:end;height:90px;gap:5px">${values.map(v=>`<div title="${v.toFixed(2)} ms" style="flex:1;background:var(--blue);height:${Math.max(2,v/(Math.max(...values)||1)*100)}%"></div>`).join('')}</div>`;};action('ping-run',()=>{const count=Number($('ping-count').value);if(!Number.isInteger(count)||count<1||count>100)throw Error('Count must be 1–100.');clearInterval(timer);lines=[];values=[];sent=0;const [mean,spread,loss]=profiles[$('ping-profile').value],target=$('ping-target').value;timer=setInterval(()=>{sent++;if(Net.randomInt(10000)<loss*10000)lines.push(`seq=${sent} Request timed out`);else{const v=Math.max(.1,mean+(Net.randomInt(20001)/10000-1)*spread);values.push(v);lines.push(`Reply from ${target}: seq=${sent} time=${v.toFixed(2)} ms`);}render();if(sent>=count){clearInterval(timer);timer=null;}},200);});action('ping-stop',()=>clearInterval(timer));cleanup=()=>clearInterval(timer);render();}
function asnLab(){$('surface').innerHTML=card('Public routing lookup',input('asn-resource','ASN or IPv4 address','AS13335')+`<div class="actions">${btn('asn-lookup','Look up RIPE Stat',true)}</div>`+out()+hint('This lookup sends only the entered public ASN or IP to RIPE NCC. It needs internet access. No result is fabricated if the service is unavailable.'));action('asn-lookup',async()=>{const raw=$('asn-resource').value.trim(),resource=/^(AS)?\d+$/i.test(raw)?'AS'+raw.replace(/^AS/i,''):raw;if(resource.startsWith('AS')){const v=Number(resource.slice(2));if(!Number.isInteger(v)||v<1||v>4294967295)throw Error('Use an ASN between 1 and 4294967295.');}else Net.ip(resource);$('output').innerHTML=hint('Looking up public routing data…');const r=await fetch('https://stat.ripe.net/data/'+(resource.startsWith('AS')?'as-overview':'prefix-overview')+'/data.json?resource='+encodeURIComponent(resource));if(!r.ok)throw Error('RIPE Stat could not complete the lookup.');const {data:d,status}=await r.json();if(status==='error')throw Error('No result from RIPE Stat.');$('output').innerHTML=stats([['Resource',resource],['Holder',d.holder||d.asns?.map(a=>a.holder).join(', ')||'Not returned'],['Announced',String(d.announced??'Not returned')],['IPv4 / IPv6 prefixes',`${d.block?.resource||d.prefix||d.type||'See RIPE Stat'}`]])+`<p style="margin-top:15px"><a target="_blank" rel="noopener" href="https://stat.ripe.net/${encodeURIComponent(resource)}">Open full RIPE Stat report</a></p>`;});}
function portsLab(){$('surface').innerHTML=card('Service lookup',`<div class="fields">${input('port-search','Search port or service','')}${select('port-proto','Protocol',['All','TCP','UDP'])}</div>${out()}`);const run=()=>{const q=$('port-search').value.toLowerCase(),p=$('port-proto').value,rows=PORTS.filter(r=>r.join(' ').toLowerCase().includes(q)&&(p==='All'||r[1].includes(p)));$('output').innerHTML=hint(rows.length+' services shown. Port assignments alone do not guarantee application identity.')+table(['Port','Transport','Service','Filter'],rows.map(r=>[r[0],r[1],esc(r[2]),`<button data-filter="${esc(r[1]==='TCP/UDP'?`tcp.port == ${r[0]} or udp.port == ${r[0]}`:`${r[1].toLowerCase()}.port == ${r[0]}`)}">Copy filter</button>`]));$('output').querySelectorAll('button').forEach(b=>b.onclick=()=>safe(()=>copy(b.dataset.filter)));};$('port-search').oninput=run;$('port-proto').onchange=run;run();}
function simulationLab(id){const spec=SCENARIOS[id];let mode=Object.keys(spec.modes)[0],index=-1,timer=null;const mount=()=>{$('surface').innerHTML=card('Scenario controls',`<div class="fields">${select('sim-mode','Scenario',Object.keys(spec.modes))}${select('sim-speed','Playback interval',[['1500','Slow'],['800','Normal'],['350','Fast']])}</div><div class="actions">${btn('sim-prev','Previous')}${btn('sim-play','Play',true)}${btn('sim-next','Next')}${btn('sim-reset','Reset')}<span id="sim-step" class="pill"></span></div>`)+card('Topology and packet flow',out('sim-topology')+out('sim-ladder'))+`<div class="grid equal">${card('Current message',out('sim-detail'))}${card('Timeline',out())}</div>`;const steps=()=>spec.modes[mode];const draw=()=>{const a=steps(),s=a[index];$('sim-step').textContent=`${Math.max(0,index+1)} / ${a.length}`;$('sim-topology').innerHTML=`<div class="topology">${spec.nodes.map((n,i)=>`${i?'<span class="wire"></span>':''}<div class="node ${s&&(s[0]===n||s[1]===n)?'selected':''}">${esc(n)}<small>${s&&s[0]===n?'SENDER':s&&s[1]===n?'RECEIVER':'DEVICE'}</small></div>`).join('')}</div>`;$('sim-ladder').innerHTML=a.slice(0,index+1).map((x,i)=>`<div class="packet-line ${i===index?'active':''}"><span>${esc(x[0])}</span><span class="route">${esc(x[2])} ›</span><span>${esc(x[1])}</span></div>`).join('');$('sim-detail').innerHTML=s?`<h3>${esc(s[2])}</h3><p>${esc(s[3])}</p><pre>Source       ${esc(s[0])}\nDestination  ${esc(s[1])}\nScenario     ${esc(mode)}\nEvent        ${esc(s[2])}</pre>`+protocolFields(id,mode,index):hint('Choose a scenario, then play or advance one event at a time.');$('output').innerHTML=a.map((x,i)=>`<div class="step"><span>${i+1}</span><div><strong class="${i===index?'positive':''}">${esc(x[2])}</strong><p>${esc(x[0])} → ${esc(x[1])}</p></div></div>`).join('');$('sim-prev').disabled=index<0;$('sim-next').disabled=index===a.length-1;};const stop=()=>{clearInterval(timer);timer=null;$('sim-play').textContent='Play';};action('sim-next',()=>{stop();index=Math.min(index+1,steps().length-1);draw();});action('sim-prev',()=>{stop();index=Math.max(-1,index-1);draw();});action('sim-reset',()=>{stop();index=-1;draw();});action('sim-play',()=>{if(timer){stop();return;}if(index===steps().length-1)index=-1;$('sim-play').textContent='Pause';timer=setInterval(()=>{index++;draw();if(index>=steps().length-1)stop();},Number($('sim-speed').value));});$('sim-mode').onchange=()=>{stop();mode=$('sim-mode').value;index=-1;draw();};cleanup=()=>clearInterval(timer);draw();};mount();}
function mtuLab(){$('surface').innerHTML=card('Fragmentation calculator',`<div class="fields">${input('packet-size','IPv4 packet size (bytes)',4000,'number')}${input('mtu','Egress MTU',1500,'number')}${input('ip-header','IPv4 header size',20,'number')}<label><input type="checkbox" id="df"> Don’t Fragment</label></div>${btn('fragment','Calculate fragments',true)}${out()}`)+card('MTU / MSS',hint('IPv4 fragment offsets are in 8-byte units. Each non-final fragment carries a payload whose length is a multiple of 8. IPv6 routers do not fragment forwarded packets.'));action('fragment',()=>{const size=Number($('packet-size').value),mtu=Number($('mtu').value),h=Number($('ip-header').value);if(![size,mtu,h].every(Number.isInteger)||h<20||h>60||h%4||size<h||size>65535||mtu<h+8)throw Error('Use valid integer IPv4 lengths: header 20–60 in multiples of 4, packet ≤65535, MTU at least header + 8.');if(size<=mtu){$('output').innerHTML=hint('The packet fits. No fragmentation is needed.');return;}if($('df').checked){$('output').innerHTML=hint('Drop packet and return ICMP type 3 / code 4 (fragmentation needed), subject to ICMP policy.',true);return;}const chunk=Math.floor((mtu-h)/8)*8;let remaining=size-h,offset=0,rows=[];while(remaining>0){const payload=Math.min(chunk,remaining);remaining-=payload;rows.push([rows.length+1,payload+h,payload,offset/8,remaining>0?1:0]);offset+=payload;}$('output').innerHTML=table(['Fragment','Total bytes','Payload','Offset (8-byte units)','MF flag'],rows)+stats([['Native IPv4 TCP MSS',mtu-40],['Native IPv4 UDP payload',mtu-28]]);});$('fragment').click();}
function tunnelLab(){$('surface').innerHTML=card('Encapsulation and overhead',`<div class="fields">${select('tunnel-kind','Tunnel / encapsulation',[['20','IP-in-IP'],['24','GRE / IPv4'],['44','GRE / IPv6'],['50','VXLAN (IPv4 outer)'],['60','WireGuard / IPv4'],['73','IPsec ESP (illustrative estimate)'],['8','MPLS (two labels)'],['4','802.1Q tag']])}${input('underlay','Outer MTU',1500,'number')}${input('payload','Inner packet size',1000,'number')}</div>${btn('encap','Build packet',true)}${out()}`);action('encap',()=>{const overhead=Number($('tunnel-kind').value),mtu=Number($('underlay').value),payload=Number($('payload').value);if(!Number.isInteger(mtu)||!Number.isInteger(payload)||mtu<=overhead||payload<1)throw Error('Use positive integer lengths and an MTU larger than overhead.');$('output').innerHTML=`<div class="topology"><div class="node selected">Outer headers<small>${overhead} bytes</small></div><div class="node">Inner packet<small>${payload} bytes</small></div></div>`+stats([['Effective inner MTU',mtu-overhead],['Total encapsulated bytes',payload+overhead],['IPv4 TCP MSS (20+20 headers)',mtu-overhead-40],['Fits underlay?',payload+overhead<=mtu?'Yes':'No']])+hint('Actual overhead depends on options, cipher, padding and outer IP version. VLAN tags increase frame length; IP MTU often remains unchanged when the link supports tagged frames.');});$('encap').click();}
function vlanLab(){$('surface').innerHTML=card('802.1Q frame builder',`<div class="fields">${input('vid','VLAN ID',10,'number','min="1" max="4094"')}${input('pcp','PCP priority',0,'number','min="0" max="7"')}${select('tag-mode','Frame',['Tagged trunk','Native VLAN untagged','QinQ'])}</div>${btn('tag','Inspect frame',true)}${out()}`);action('tag',()=>{const vid=Number($('vid').value),pcp=Number($('pcp').value);if(!Number.isInteger(vid)||vid<1||vid>4094||!Number.isInteger(pcp)||pcp<0||pcp>7)throw Error('VLAN ID must be 1–4094; PCP must be 0–7.');const m=$('tag-mode').value,tci=(pcp<<13)|vid;$('output').innerHTML=table(['Field','Value'],[['Destination MAC','02:11:22:33:44:55'],['Source MAC','02:aa:bb:cc:dd:ee'],...(m==='Native VLAN untagged'?[]:[['TPID',m==='QinQ'?'0x88a8 (outer) / 0x8100 (inner)':'0x8100'],['TCI','0x'+tci.toString(16).padStart(4,'0')],['PCP / DEI / VID',`${pcp} / 0 / ${vid}`]]),['EtherType','0x0800 (IPv4)']])+hint(`A ${m==='QinQ'?'double tag adds 8':m==='Native VLAN untagged'?'native untagged frame adds 0':'single tag adds 4'} bytes relative to the original Ethernet frame. Native VLAN behavior must agree on both trunk ends.`);});$('tag').click();}
function eigrpLab(){$('surface').innerHTML=card('Successor / feasible successor',`<div class="fields">${input('fd','Current feasible distance',1000,'number')}${input('rd','Candidate reported distance',800,'number')}${input('distance','Candidate total distance',1400,'number')}</div>${btn('dual','Evaluate feasibility',true)}${out()}`)+card('Classic metric',`<div class="fields">${input('bw','Minimum bandwidth (kbps)',100000,'number')}${input('delay','Sum of delay (microseconds)',100,'number')}</div>${btn('metric','Calculate default metric')}${out('metric-result')}`);action('dual',()=>{const fd=Number($('fd').value),rd=Number($('rd').value),d=Number($('distance').value);if(![fd,rd,d].every(x=>Number.isInteger(x)&&x>=0)||d<rd)throw Error('Distances must be nonnegative integers; total distance must be at least reported distance.');$('output').innerHTML=stats([['Feasibility condition',`${rd} < ${fd}`],['Loop-free candidate?',rd<fd?'Yes':'No']])+hint(rd<fd?'This candidate satisfies the feasibility condition. It can provide a loop-free alternate.':'This candidate fails the strict RD < FD test. DUAL may need a diffusing computation; a failed test does not prove the path itself is a loop.');});action('metric',()=>{const bw=Number($('bw').value),delay=Number($('delay').value);if(bw<=0||delay<0||!Number.isFinite(bw)||!Number.isFinite(delay))throw Error('Use positive bandwidth and nonnegative delay.');$('metric-result').innerHTML=stats([['Classic default metric',Math.floor(256*(Math.floor(1e7/bw)+Math.floor(delay/10)))]])+hint('Default classic K values: K1=K3=1; other K values 0. Wide metrics use different scaling.');});$('dual').click();$('metric').click();}
